1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.StringUtil;
4	import org.jsoup.nodes.Element;
5	import org.jsoup.parser.Parser;
6	
7	/**
8	 Parses and sanitizes the text of an allowed {@code <style>} element, one stylesheet rule at a time. Like
9	 {@link StyleCleaner}, it is a small hand scanner rather than a full CSS parser: each scope (the whole sheet, or an
10	 at-rule block) is split into qualified rules ({@code selector { declarations }}) and statements ({@code @import …},
11	 {@code @media …}) while tracking the actual nesting of strings, parentheses, block comments, and CSS backslash
12	 escapes, so punctuation inside strings, functions, or comments cannot break out of its rule or declaration. A
13	 brace at the top level of a scope always bounds a block (a brace inside a balanced function does not), and a '}'
14	 after an unclosed function is honored as the recovery boundary, so the malformed declaration invalidates only
15	 itself and never swallows the rules after the block. Nested blocks (rules inside an {@code @media}/
16	 {@code @supports} block) are handled recursively and independently.
17	
18	 <p>Selectors, at-rule preludes, ordinary declaration names and values (numbers, colors, fonts, custom
19	 properties), whitespace, comments, and duplicates are emitted verbatim in source order. {@code @import}
20	 references, every {@code url(…)} argument (including one nested inside another function), and the legacy
21	 {@code expression(…)} function are checked with the same URL policy and the same obfuscation handling (mixed
22	 case, HTML entities, percent-encoding, control bytes, and CSS escapes) as an inline {@code style} attribute. The
23	 HTML parser keeps {@code <style>} contents as raw text and never applies HTML entities to it, so rule and
24	 declaration boundaries are always scanned in the raw text (an entity such as {@code &#123;} cannot forge a block
25	 boundary), while entities within an already bounded statement or declaration are decoded only for the safety
26	 decision; a surviving fragment always keeps its original spelling.</p>
27	
28	 <p>A rejected import or declaration takes only itself; its rule's surviving selectors and declarations are kept,
29	 and no safe content in the same rule is lost. Unclosed strings, parentheses, or comments, repeated separators, and
30	 truncated imports and nested references never throw: rules whose boundaries can still be determined are handled
31	 independently, and only the unbounded or undecidable fragment is discarded. When no rule survives the result is
32	 empty, in which case the caller removes the {@code <style>} element.</p>
33	
34	 <p>The cleaner is stateless and thread-safe; all per-sheet state lives on the local parse stack.</p>
35	 */
36	final class StyleSheetCleaner {
37	    // bound recursion so a deliberately or accidentally deep nesting cannot exhaust a small (e.g. virtual-thread)
38	    // stack; this matches the parser's own max depth and is far beyond any realistically authored stylesheet
39	    private static final int MaxNesting = 512;
40	
41	    private final StyleCleaner sc;
42	
43	    private StyleSheetCleaner(Safelist safelist, String tagName, Element el) {
44	        this.sc = StyleCleaner.create(safelist, tagName, el);
45	    }
46	
47	    /**
48	     Cleans the raw text of an allowed {@code <style>} element rule by rule, preserving the order and original
49	     spelling of every rule, declaration, and value that survives.
50	     @return the cleaned stylesheet text, or {@code null} when no rule survives (in which case the element is removed)
51	     */
52	    static String clean(Safelist safelist, String tagName, Element el, String css) {
53	        return new StyleSheetCleaner(safelist, tagName, el).cleanSheet(css);
54	    }
55	
56	    private String cleanSheet(String css) {
57	        if (StringUtil.isBlank(css)) return css; // no rules at all: keep the element as-is
58	        int[] match = sc.parenMatches(css); // every parenthesis's mate, computed once and shared by every scope
59	        int[] opens = new int[css.length()]; // the per-scope open stack; block boundaries always reset its depth
60	        StringBuilder out = StringUtil.borrowBuilder();
61	        process(css, 0, css.length(), 0, match, opens, out);
62	        return out.length() == 0 ? null : StringUtil.releaseBuilder(out);
63	    }
64	
65	    /**
66	     Walks one stylesheet scope (the whole sheet, or an at-rule block) and appends every surviving statement and
67	     rule to {@code out} in source order. A parenthesis closes a function only when its mate lies within the
68	     scope, so a semicolon stays function content only for a function that closes before the block ends.
69	     */
70	    private void process(String css, int start, int end, int depth, int[] match, int[] opens, StringBuilder out) {
71	        int parenDepth = 0;
72	        int ruleStart = start;
73	        int i = start;
74	        while (i < end) {
75	            char c = css.charAt(i);
76	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\{' or '\;'
77	                i += 2;
78	                continue;
79	            }
80	            if (c == '"' || c == '\'') {
81	                int[] quote = sc.scanQuoted(css, i + 1, c);
82	                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // recover at a newline/';', else run to scope end
83	                continue;
84	            }
85	            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
86	                int close = css.indexOf("*/", i + 2);
87	                // a closer beyond this scope cannot close the comment inside it: a CSS comment runs to EOF, so the
88	                // comment and everything after it in this scope is an unbounded fragment. The statement accumulated
89	                // before the comment still has a determinable boundary and is validated on its own merits; a later
90	                // scope (after the block's real '}') is unaffected and parses independently.
91	                if (close < 0 || close >= end) {
92	                    emitStatement(css, ruleStart, i, false, out);
93	                    ruleStart = end;
94	                    i = end;
95	                } else {
96	                    i = close + 2;
97	                }
98	                continue;
99	            }
100	            if (c == '(') {
101	                opens[parenDepth++] = i;
102	            } else if (c == ')') {
103	                if (parenDepth > 0) parenDepth--; // a stray ')' outside any function is ordinary separator text
104	            } else if (c == '{' && parenDepth == 0) {
105	                int close = matchingBrace(css, i + 1, end, match, opens);
106	                int bodyEnd = close >= 0 ? close : end;
107	                emitRule(css, ruleStart, i, bodyEnd, depth, match, opens, out);
108	                parenDepth = 0; // braces always bound blocks; an unclosed function does not carry into the next rule
109	                ruleStart = close >= 0 ? close + 1 : end;
110	                i = ruleStart;
111	                continue;
112	            } else if (c == '}' && parenDepth == 0) {
113	                // a stray '}' closes no block opened in this scope: validate the prelude before it as a statement
114	                emitStatement(css, ruleStart, i, false, out);
115	                parenDepth = 0;
116	                ruleStart = i + 1;
117	            }
118	            // a '{' or '}' inside an unclosed function is ordinary (invalid) declaration text: block boundaries are
119	            // established by matchingBrace, which honors '}' so the function cannot swallow the following rules
120	            else if (c == ';' && (parenDepth == 0 || match[opens[parenDepth - 1]] < 0
121	                || match[opens[parenDepth - 1]] >= end)) {
122	                // a ';' ends the statement unless it is content of a function that closes later in this scope
123	                emitStatement(css, ruleStart, i, true, out);
124	                parenDepth = 0;
125	                ruleStart = i + 1;
126	            }
127	            i++;
128	        }
129	        if (ruleStart < end) emitStatement(css, ruleStart, end, false, out); // a trailing statement without ';'
130	    }
131	
132	    /**
133	     Validates and emits one qualified rule (or at-rule block): the prelude is copied verbatim when it carries no
134	     unsafe reference, and the block is emitted only when its body yields surviving content. Nested blocks are
135	     processed into their own buffer first, so an empty body never leaves an empty rule behind.
136	     */
137	    private void emitRule(String css, int preludeStart, int brace, int bodyEnd, int depth, int[] match, int[] opens,
138	                          StringBuilder out) {
139	        int p = sc.skipSpaceAndComments(css, preludeStart, brace);
140	        if (p < 0 || p >= brace) return; // an unterminated comment or an empty prelude (a stray '{') is not a rule
141	        if (!preludeIsSafe(css, p, brace)) return;
142	        StringBuilder body = StringUtil.borrowBuilder();
143	        // every block body is walked as a rule scope: nested rules (@media/@supports) recurse, and declarations
144	        // (@font-face/@page, or a qualified rule's contents) validate as declarations
145	        if (depth < MaxNesting) process(css, brace + 1, bodyEnd, depth + 1, match, opens, body);
146	        if (body.length() == 0) {
147	            StringUtil.releaseBuilderVoid(body);
148	            return;
149	        }
150	        out.append(css, preludeStart, brace + 1); // selector/at-rule prelude and the opening brace, verbatim
151	        out.append(body);
152	        StringUtil.releaseBuilderVoid(body);
153	        // a block whose '}' was lost (e.g. swallowed by an unterminated comment) is closed here, exactly as a
154	        // browser closes it at EOF, so the output never carries an orphan opening brace and stays idempotent
155	        out.append('}');
156	    }
157	
158	    /**
159	     A selector/at-rule prelude is inert text except for an actual reference it may carry. The leading at-keyword
160	     of an at-rule prelude ({@code @media}, {@code @supports}) is skipped, since an '@' cannot start a declaration
161	     value; the remainder is checked like an ordinary declaration value.
162	     */
163	    private boolean preludeIsSafe(String css, int start, int end) {
164	        String raw = css.substring(start, end);
165	        String check = raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
166	        int len = check.length();
167	        int s = sc.skipSpaceAndComments(check, 0, len);
168	        if (s < 0 || s >= len) return false;
169	        if (check.charAt(s) == '@') {
170	            StringBuilder atName = new StringBuilder();
171	            int nameEnd = sc.scanIdent(check, s + 1, len, atName);
172	            if (nameEnd == s + 1) return false; // a bare '@' is not an at-rule
173	            s = sc.skipSeparators(check, nameEnd, len);
174	            if (s < 0 || s >= len) return true; // an at-keyword with no prelude condition
175	        }
176	        return sc.referencesAreSafe(check, s, len);
177	    }
178	
179	    /**
180	     Validates and emits one top-level statement between separators. Whitespace- or comment-only fragments are
181	     skipped; an {@code @import}'s reference must pass the URL rules, any other at-statement passes when its own
182	     references pass, and a declaration-shaped statement passes the same declaration rules as an inline
183	     {@code style} attribute (so the legacy script-entry properties are denied everywhere). A surviving statement
184	     keeps its source spelling, and the source semicolon that terminated it ({@code terminated}) is emitted so
185	     adjacent statements stay separated; a block- or EOF-bounded statement gains none.
186	     */
187	    private void emitStatement(String css, int start, int end, boolean terminated, StringBuilder out) {
188	        int p = sc.skipSpaceAndComments(css, start, end);
189	        if (p < 0 || p >= end) return; // an unterminated comment makes the statement unbounded
190	        int q = end;
191	        while (q > p && StyleCleaner.isCssSpace(css.charAt(q - 1))) q--;
192	        if (p == q) return;
193	        String raw = css.substring(start, q);
194	        String check = raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
195	        int len = check.length();
196	        int s = sc.skipSpaceAndComments(check, 0, len);
197	        if (s < 0 || s >= len) return;
198	        boolean safe;
199	        int keptEnd = q; // source end of the surviving text (usually the whole trimmed statement)
200	        if (check.charAt(s) == '@') {
201	            StringBuilder atName = new StringBuilder();
202	            int nameEnd = sc.scanIdent(check, s + 1, len, atName);
203	            if (nameEnd == s + 1) return; // a bare '@' is not an at-rule
204	            if (atName.toString().equalsIgnoreCase("import")) {
205	                safe = sc.isSafeImportDeclaration(check, s, len);
206	            } else {
207	                // other at-statements (@charset, @namespace, an unknown prelude): skip the at-keyword, then check
208	                // the remainder like an ordinary value
209	                int r = sc.skipSeparators(check, nameEnd, len);
210	                safe = r >= 0 && (r >= len || sc.referencesAreSafe(check, r, len));
211	            }
212	        } else {
213	            // a declaration-shaped statement (including the contents of an @font-face/@page block)
214	            int to = sc.safeDeclarationRange(check, 0, len, false);
215	            safe = to > 0;
216	            if (safe && check == raw) keptEnd = start + to; // trim exactly as the inline cleaner would
217	        }
218	        if (safe) {
219	            out.append(css, start, keptEnd);
220	            if (terminated) out.append(';');
221	        }
222	    }
223	
224	    /**
225	     Finds the '}' that closes a block, skipping strings, comments, escapes, parentheses, and nested braces. A '{'
226	     inside a balanced function never starts a nested block, and a '}' inside a balanced function never closes the
227	     outer block; but a '}' after an unclosed '(' (a function whose ')' is missing within the scope) is honored as
228	     the block boundary, the same parse-error recovery a browser performs, so the malformed declaration invalidates
229	     only itself and the following rules still parse independently.
230	     */
231	    private int matchingBrace(String css, int from, int end, int[] match, int[] opens) {
232	        int braceDepth = 1;
233	        int parenDepth = 0;
234	        int i = from;
235	        while (i < end) {
236	            char c = css.charAt(i);
237	            if (c == '\\') { i += 2; continue; }
238	            if (c == '"' || c == '\'') {
239	                int[] quote = sc.scanQuoted(css, i + 1, c);
240	                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // closed quote, or recovery at a newline/';'/EOF
241	                continue;
242	            }
243	            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
244	                int close = css.indexOf("*/", i + 2);
245	                if (close < 0 || close >= end) return -1;
246	                i = close + 2;
247	                continue;
248	            }
249	            if (c == '(') {
250	                opens[parenDepth++] = i;
251	            } else if (c == ')') {
252	                if (parenDepth > 0) parenDepth--;
253	            } else if (parenDepth == 0 && c == '{') {
254	                braceDepth++;
255	            } else if (c == '}') {
256	                // a '}' bounds the block only when the innermost '(' is closed within the scope; otherwise the
257	                // function is unclosed and this '}' is the browser-style recovery point
258	                int open = parenDepth > 0 ? opens[parenDepth - 1] : -1;
259	                boolean insideClosedFunction = open >= 0 && match[open] >= 0 && match[open] < end;
260	                if (!insideClosedFunction) {
261	                    braceDepth--;
262	                    if (braceDepth == 0) return i;
263	                }
264	            }
265	            i++;
266	        }
267	        return -1;
268	    }
269	}
