162	        return numDiscarded == 0 && errorList.isEmpty();
163	    }
164	
165	    /**
166	     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
167	     */
168	    private final class CleaningVisitor implements NodeVisitor {
169	        private int numDiscarded = 0;
170	        private final Element root;
171	        private Element destination; // current element to append nodes to
172	        // style elements whose stylesheet data nodes were all rejected are removed at their tail; an element with at
173	        // least one surviving data node is kept, mirroring an attribute whose value still has safe declarations
174	        private final Set<Element> rejectedStyleElements = new HashSet<>();
175	        private final Set<Element> keptStyleElements = new HashSet<>();
