182	        @Override public void head(Node source, int depth) {
183	            if (source instanceof Element) {
184	                Element sourceEl = (Element) source;
185	
186	                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
187	                    ElementMeta meta = createSafeElement(sourceEl);
188	                    Element destChild = meta.el;
189	                    destination.appendChild(destChild);
190	
191	                    numDiscarded += meta.numAttribsDiscarded;
192	                    destination = destChild;
193	                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
194	                    numDiscarded++;
195	                }
196	            } else if (source instanceof TextNode) {
197	                TextNode sourceText = (TextNode) source;
198	                TextNode destText = new TextNode(sourceText.getWholeText());
199	                destination.appendChild(destText);
200	            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
201	                DataNode sourceData = (DataNode) source;
202	                String data = sourceData.getWholeData();
203	                Node parent = source.parent();
204	                if (parent.normalName().equals("style")) { // an allowed <style> element: clean its stylesheet text
205	                    String cleaned = safelist.cleanStyleSheet(parent.normalName(), (Element) parent, data);
206	                    if (cleaned == null) { // this data node's rules were all invalid
207	                        numDiscarded++;
208	                        rejectedStyleElements.add(destination);
209	                    } else {
210	                        if (!cleaned.equals(data)) numDiscarded++; // rules or declarations were dropped/normalized
211	                        keptStyleElements.add(destination);
212	                        destination.appendChild(new DataNode(cleaned));
213	                    }
214	                } else {
215	                    destination.appendChild(new DataNode(data));
216	                }
217	            } else { // else, we don't care about comments, xml proc instructions, etc
218	                numDiscarded++;
219	            }
220	        }
221	
222	        @Override public void tail(Node source, int depth) {
223	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
224	                Element self = destination;
225	                destination = destination.parent(); // would have descended, so pop destination stack
226	                boolean rejected = rejectedStyleElements.remove(self);
227	                boolean kept = keptStyleElements.remove(self);
228	                if (rejected && !kept) self.remove(); // remove a <style> element whose content was wholly invalid
229	            }
230	        }
231	    }
232	
233	    private int copySafeNodes(Element source, Element dest) {
234	        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
235	        cleaningVisitor.traverse(source);
236	        return cleaningVisitor.numDiscarded;
237	    }
238	
239	    private ElementMeta createSafeElement(Element sourceEl) {
240	        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
241	        String sourceTag = sourceEl.tagName();
242	        Attributes destAttrs = dest.attributes();
243	        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy
244	
245	        int numDiscarded = 0;
246	        Attributes sourceAttrs = sourceEl.attributes();
247	        for (Attribute sourceAttr : sourceAttrs) {
248	            if (safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr)) { // will keep this attr
249	                String key = sourceAttr.getKey();
250	                String value = sourceAttr.getValue();
251	
252	                if (Safelist.isSrcset(key)) { // clean the srcset candidates; drop the attribute if none survive
253	                    String cleaned = safelist.cleanSrcset(sourceTag, sourceEl, value);
254	                    if (cleaned == null) {
255	                        numDiscarded++;
256	                        continue;
257	                    }
258	                    if (!cleaned.equals(value))
259	                        numDiscarded++; // candidates were dropped or normalized
260	                    value = cleaned;
261	                } else if (Safelist.isStyle(key)) { // clean inline CSS declaration by declaration; drop if none survive
262	                    String cleaned = safelist.cleanStyle(sourceTag, sourceEl, value);
263	                    if (cleaned == null) {
264	                        numDiscarded++;
265	                        continue;
266	                    }
267	                    if (!cleaned.equals(value))
268	                        numDiscarded++; // unsafe or malformed declarations were dropped
269	                    value = cleaned;
270	                } else if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
271	                    value = sourceEl.absUrl(key);
272	                    if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
273	                        value = sourceAttr.getValue();
274	                }
275	                Range.AttributeRange range = sourceAttrs.sourceRange(key);
276	                destAttrs.put(key, value);
277	                NodeInternals.attributeRange(destAttrs, key, range);
278	            } else
279	                numDiscarded++;
280	        }
281	
282	        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
283	        // special case for <a href rel=nofollow>, only apply to external links:
284	        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
285	            String href = sourceEl.absUrl("href");
286	            if (!href.isEmpty()) {
287	                try {
288	                    URL baseUrl = new URL(sourceEl.baseUri());
289	                    URL linkUrl = new URL(href);
290	                    String baseHost = baseUrl.getHost();
291	                    if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
292	                        enforcedAttrs.remove("rel");
293	                } catch (MalformedURLException ignored) {}
294	            }
295	        }
296	
297	        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
298	        for (Attribute enforcedAttr : enforcedAttrs) {
299	            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
300	            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
301	        }
302	        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
303	        return new ElementMeta(dest, numDiscarded);
304	    }
305	
306	    private static class ElementMeta {
307	        Element el;
308	        int numAttribsDiscarded;
309	
310	        ElementMeta(Element el, int numAttribsDiscarded) {
311	            this.el = el;
312	            this.numAttribsDiscarded = numAttribsDiscarded;
313	        }
314	    }
315	
316	}
