233	        Document clean = cleanDoc(html, Base, sheetSafelist());
234	        assertEquals("p{color:red}", clean.selectFirst("style").data());
235	        assertEquals("color:red", clean.selectFirst("div").attr("style"));
236	        assertEquals("https://example.com/x.png", clean.selectFirst("img").attr("src"));
237	    }
