239	    @Test void cleaningIsIdempotentAndStable() {
240	        Document dirty = Jsoup.parseBodyFragment(
241	            "<style>@import url(https://example.com/x.css); p { color:red; background: url(javascript:1); } "
242	                + "@media screen { b { width:1px; background: url(//cdn/x.png); } }</style>", Base);
243	        Cleaner cleaner = new Cleaner(sheetSafelist());
244	        Document once = cleaner.clean(dirty);
245	        Document twice = cleaner.clean(once);
246	        assertEquals(once.body().html(), twice.body().html());
247	        assertEquals(once.body().html(), cleaner.clean(twice).body().html());
248	        assertTrue(Cleaner.isValid(once.body().html(), sheetSafelist()));
249	    }
250	
251	    @Test void aFullySafeStylesheetIsNotRewritten() {
252	        // a compact safe sheet passes through unchanged, so validation and cleaning agree
253	        String css = "p{color:red}@media screen{b{width:1px}}";
254	        assertEquals(css, sheet(css));
255	        assertTrue(Cleaner.isValid("<style>" + css + "</style>", sheetSafelist()));
256	    }
257	
258	    @Test void cleaningDoesNotModifyInputDocument() {
259	        Document dirty = Jsoup.parseBodyFragment(
260	            "<style>p{color:red;background:url(javascript:1)}</style>"
261	                + "<div style=\"background:url(javascript:1)\">x</div>", Base);
262	        String before = dirty.body().html();
263	        String beforeData = dirty.selectFirst("style").data();
264	        String beforeStyle = dirty.selectFirst("div").attr("style");
265	        new Cleaner(sheetSafelist()).clean(dirty);
266	        new Cleaner(sheetSafelist()).clean(dirty);
267	        assertEquals(before, dirty.body().html());
268	        assertEquals(beforeData, dirty.selectFirst("style").data());
269	        assertEquals(beforeStyle, dirty.selectFirst("div").attr("style"));
270	    }
271	
272	    @Test void rejectedUrlNeverAppearsInOutputOrTree() {
273	        Document clean = cleanDoc("<style>p{background:url(javascript:alert(1))}</style>", Base, sheetSafelist());
274	        assertFalse(clean.toString().contains("javascript"));
275	        clean.getAllElements().forEach(el -> assertFalse(el.data().contains("javascript")));
276	    }
277	
278	    @Test void isValidTracksStylesheetRewrites() {
279	        assertTrue(Cleaner.isValid("<style>p{color:red}</style><p>x</p>", sheetSafelist()));
280	        assertFalse(Cleaner.isValid("<style>p{background:url(javascript:1)}</style>", sheetSafelist()));
281	        assertFalse(Cleaner.isValid("<style>@import url(javascript:1)</style>", sheetSafelist()));
282	    }
283	
284	    @Test void nestingBeyondTheDepthBoundNeverThrows() {
285	        // pathological nesting is bounded rather than overflowing a small stack; the result is safe either way
286	        StringBuilder css = new StringBuilder();
287	        for (int i = 0; i < 600; i++) css.append("@media screen{");
288	        css.append("p{color:red}");
289	        for (int i = 0; i < 600; i++) css.append("}");
290	        String out = sheet(css.toString());
291	        if (out != null) assertFalse(out.contains("javascript"));
292	    }
293	
294	    @Test void cleansThroughPublicDocumentEntryPoint() {
295	        Document dirty = Jsoup.parseBodyFragment(
296	            "<div><style>p{color:red;background:url(javascript:1)}</style><p>x</p></div>", Base);
297	        Document clean = new Cleaner(sheetSafelist()).clean(dirty);
298	        Element style = clean.body().selectFirst("style");
299	        assertNotNull(style);
300	        assertEquals("p{color:red;}", style.data());
301	        // the cleaned document is fully isolated from the parsed input
302	        assertNotSame(dirty.body().selectFirst("style"), style);
303	    }
304	}
