58	    private String clean(String value) {
59	        StringBuilder out = StringUtil.borrowBuilder();
60	        int length = value.length();
61	        int[] match = parenMatches(value); // index of each parenthesis's mate, or -1 when unmatched
62	        int[] opens = new int[length]; // positions of the currently open parentheses
63	        int segStart = 0;
64	        int parenDepth = 0;
65	        boolean segmentBad = false; // this segment already contains a malformed construct
66	        int i = 0;
67	        while (i < length) {
68	            char c = value.charAt(i);
69	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
70	                i += 2;
71	                continue;
72	            }
73	            if (c == '"' || c == '\'') {
74	                int[] quote = scanQuoted(value, i + 1, c);
75	                if (quote[1] == 1) {
