264	    /** Appends a surviving declaration, separated from any earlier ones by a single semicolon. */
265	    private void append(StringBuilder out, String value, int from, int to) {
266	        if (out.length() > 0) out.append(';');
267	        out.append(value, from, to);
268	    }
