270	    /**
271	     Validates an entire {@code @import} statement: its leading reference (a quoted URL or a {@code url(...)}) must
272	     * pass the URL rules, and any trailing layer/media/supports conditions must themselves contain no unsafe
273	     * reference.
274	     */
275	    boolean isSafeImportDeclaration(String value, int at, int end) {
276	        int i = at + 1;
277	        StringBuilder atName = new StringBuilder();
278	        i = scanIdent(value, i, end, atName);
279	        if (!atName.toString().equalsIgnoreCase("import")) return false;
280	        int sep = skipSeparators(value, i, end);
281	        if (sep < 0 || sep >= end) return false;
282	        i = sep;
283	        int afterRef;
284	        char c = value.charAt(i);
285	        if (c == '"' || c == '\'') {
286	            int[] quote = scanQuoted(value, i + 1, c);
287	            if (quote[1] != 1) return false;
288	            if (!safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quote[0])))) return false;
289	            afterRef = quote[0] + 1;
290	        } else if (isIdentStart(c) || c == '-' || c == '\\') {
291	            StringBuilder fnName = new StringBuilder();
292	            int nameEnd = scanIdent(value, i, end, fnName);
293	            int k = skipSeparators(value, nameEnd, end);
294	            if (k < 0 || k >= end || value.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
295	            int argEnd = matchingParen(value, k + 1, end);
296	            if (argEnd < 0 || !isSafeUrlArgument(value, k + 1, argEnd)) return false;
297	            afterRef = argEnd + 1;
298	        } else {
299	            return false;
300	        }
301	        return referencesAreSafe(value, afterRef, end);
302	    }
