304	    /**
305	     Advances past CSS whitespace and complete block comments. A comment is inert token separators (a browser removes
306	     it before tokenization), so its text is never inspected for a concealed reference; an unterminated comment is
307	     still an unbounded fragment and yields {@code -1}, rejecting only the declaration that contains it.
308	     */
309	    int skipSpaceAndComments(String value, int i, int end) {
310	        while (i < end) {
311	            char c = value.charAt(i);
312	            if (isCssSpace(c)) { i++; continue; }
313	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
314	                int close = value.indexOf("*/", i + 2);
315	                if (close < 0 || close >= end) return -1;
316	                i = close + 2;
317	                continue;
318	            }
319	            break;
320	        }
321	        return i;
322	    }
323	
324	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url /**\/ ( ... )}). */
325	    int skipSeparators(String value, int i, int end) {
326	        return skipSpaceAndComments(value, i, end);
327	    }
328	
329	    /**
330	     Tests whether a comment-only separator (no whitespace) from {@code nameEnd} glues the preceding identifier run
331	     to another identifier run that is itself followed (optionally via separators) by {@code (}. A comment wedged
332	     between two identifier runs ({@code ur/**\/l( ... )} or {@code expr/**\/ession( ... )}) does not join them under
333	     a strict CSS tokenizer, but a lenient engine could read the glued run as a single function token; such a
334	     declaration is rejected rather than risk a split {@code url} or {@code expression} escaping recognition. Real
335	     whitespace keeps the runs distinct tokens, and two bare runs without a following call ({@code a/**\/b}) stay
336	     untouched. The second run is read with full escape semantics so that an escaped continuation such as
337	     {@code ur/**\/\6c( ... )} is just as ambiguous.
338	     */
339	    private boolean commentGluesIdentToCall(String value, int nameEnd, int end) {
340	        int i = nameEnd;
341	        boolean sawComment = false;
342	        while (i < end) {
343	            char c = value.charAt(i);
344	            if (isCssSpace(c)) return false; // real whitespace keeps the two runs distinct tokens
345	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
346	                int close = value.indexOf("*/", i + 2);
347	                if (close < 0 || close > end) return false;
348	                sawComment = true;
349	                i = close + 2;
350	                continue;
351	            }
352	            break; // reached the start of whatever the separator abuts
353	        }
354	        if (!sawComment) return false;
355	        if (i >= end || !(isIdentStart(value.charAt(i)) || value.charAt(i) == '\\'))
356	            return false; // the separator must glue onto another identifier run
357	        StringBuilder glued = new StringBuilder();
358	        int k = scanIdent(value, i, end, glued);
359	        k = skipSeparators(value, k, end);
360	        return k >= 0 && k < end && value.charAt(k) == '(';
361	    }
362	
363	    /**
364	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
365	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}. The name is
366	     * the plain identifier run starting at {@code nameStart}; a comment appended to the name cannot change the
367	     * comparison.
368	     */
369	    private boolean isDangerousProperty(String value, int nameStart) {
370	        int p = nameStart;
371	        while (p < value.length() && isIdentChar(value.charAt(p))) p++;
372	        String name = value.substring(nameStart, p);
373	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
374	    }
