376	    /**
377	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
378	     recognized exactly as in declaration splitting. Block comments and the contents of ordinary quoted strings are
379	     inert token separators (their text is emitted verbatim but never fetched or tokenized as a call); a quoted
380	     string is still checked when it is the actual argument of a {@code url()} call. Every {@code url(...)}
381	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is read with full CSS
382	     escape semantics, so a hex or character escape, consecutive backslashes, or a case change in the function name
383	     ({@code \75 rl(...)}, a backslash-escaped {@code URL}, {@code \65 xpression(...)}) reaches the same decision as the plain
384	     spelling. Unbalanced parentheses, an unterminated string or comment, or any failed reference check rejects the
385	     declaration.
386	     */
387	    boolean referencesAreSafe(String value, int start, int end) {
388	        int parenDepth = 0;
389	        int i = start;
390	        while (i < end) {
391	            char c = value.charAt(i);
392	            if (c == '"' || c == '\'') {
393	                int[] quote = scanQuoted(value, i + 1, c);
394	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
395	                // an identifier run glued directly to the string and followed by a call (e.g. u"rl"(...)) is a
396	                // syntax error a strict browser discards but a lenient one could read as one escaped function name
397	                if (stringGluesIdentToCall(value, i, quote[0], end)) return false;
398	                // ordinary string content is inert: it is never fetched as a reference (a quoted url() argument is
399	                // checked separately by isSafeUrlArgument)
400	                i = quote[0] + 1;
401	                continue;
402	            }
403	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
404	                int close = value.indexOf("*/", i + 2);
405	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
406	                i = close + 2; // comment text is inert token separators, never a concealed declaration or call
407	                continue;
408	            }
409	            if (c == '(') { parenDepth++; i++; continue; }
410	            if (c == ')') {
411	                if (parenDepth == 0) return false; // unmatched ')'
412	                parenDepth--;
413	                i++;
414	                continue;
415	            }
416	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
417	            if (isIdentStart(c) || c == '-' || c == '\\') {
418	                StringBuilder decoded = new StringBuilder();
419	                int nameEnd = scanIdent(value, i, end, decoded);
420	                String fnName = decoded.toString();
421	                int j = skipSeparators(value, nameEnd, end);
422	                if (j < 0) return false; // an unterminated comment after the name rejects the declaration
423	                if (commentGluesIdentToCall(value, nameEnd, end)) return false; // e.g. ur/**/l(...)
424	                if (j < end && value.charAt(j) == '(') {
425	                    int argEnd = matchingParen(value, j + 1, end);
426	                    if (argEnd < 0) return false;
427	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
428	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
429	                    if (!isPlainName(fnName)) return false;
430	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
431	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
432	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
433	                    continue;
434	                }
435	                i = nameEnd;
436	                continue;
437	            }
438	            i++;
439	        }
440	        return parenDepth == 0;
441	    }
