443	    /** Tests that a function name is a plain identifier, with no escape that decoded to punctuation or whitespace. */
444	    private static boolean isPlainName(String name) {
445	        int length = name.length();
446	        if (length == 0) return false;
447	        for (int k = 0; k < length; k++) {
448	            char c = name.charAt(k);
449	            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
450	                || (c >= '0' && c <= '9') || c == '-' || c == '_';
451	            if (!ok) return false;
452	        }
453	        return true;
454	    }
