456	    /**
457	     Reads a CSS identifier token starting at {@code from} with full escape semantics: plain identifier characters
458	     (including a leading run of dashes), single-character escapes (a backslash before any character such as u or '(', or a doubled
459	     {@code \\}), and hex escapes ({@code \75}, up to six hex digits) together with the single whitespace
460	     delimiter that may follow one ({@code \75 rl} is therefore one token, exactly as a browser reads it). The
461	     decoded code points are appended to {@code decoded}, and the index just past the token is returned. The decoded
462	     form is what a function name is compared against, so a hex-escaped, character-escaped, doubled-backslash, or
463	     differently cased {@code url} or {@code expression} cannot hide from the reference checks.
464	     */
465	    int scanIdent(String value, int from, int end, StringBuilder decoded) {
466	        int i = from;
467	        while (i < end) {
468	            char c = value.charAt(i);
469	            if (c == '\\') {
470	                int[] escape = consumeEscape(value, i, end);
471	                if (escape[1] >= 0) decoded.appendCodePoint(escape[1]);
472	                i = escape[0];
473	                continue;
474	            }
475	            if (isIdentChar(c)) { decoded.append(c); i++; continue; }
476	            break;
477	        }
478	        return i;
479	    }
480	
481	    /**
482	     Consumes one CSS escape sequence beginning at the backslash {@code i}. Returns {@code [next, codePoint]}:
483	     {@code next} is the index past the escape (including the single whitespace delimiter a hex run may carry, a
484	     CRLF pair counting as one delimiter), and {@code codePoint} is the decoded code point. Per the CSS spec a NUL,
485	     surrogate, or out-of-range value becomes U+FFFD; a lone trailing backslash has no escape ({@code codePoint} is
486	     {@code -1}) and is left to the caller as a stray character.
487	     */
488	    private static int[] consumeEscape(String value, int i, int end) {
489	        if (i + 1 >= end) return new int[] {end, -1};
490	        char next = value.charAt(i + 1);
491	        if (isHex(next)) {
492	            int h = i + 1;
493	            int e = h;
494	            while (e < end && e - h < 6 && isHex(value.charAt(e))) e++;
495	            int code = Integer.parseInt(value.substring(h, e), 16);
496	            int after = e;
497	            if (after < end && isCssSpace(value.charAt(after))) {
498	                after++; // the single delimiter whitespace is part of the hex escape
499	                if (after - e == 2 && value.charAt(e) == '\r' && after < end && value.charAt(after) == '\n') after++;
500	            }
501	            if (code == 0 || code > Character.MAX_CODE_POINT
502	                || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
503	                code = 0xFFFD;
504	            return new int[] {after, code};
505	        }
506	        return new int[] {i + 2, next};
507	    }
