587	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
588	    private boolean freeTextImportIsSafe(String text, int from, int end) {
589	        int i = skipSeparators(text, from, end);
590	        if (i < 0) return false;
591	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
592	        char c = text.charAt(i);
593	        if (c == '"' || c == '\'') {
594	            int[] quote = scanQuoted(text, i + 1, c);
595	            if (quote[1] != 1) return false;
596	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
597	        }
598	        if (isIdentStart(c) || c == '-' || c == '\\') {
599	            StringBuilder fnName = new StringBuilder();
600	            int nameEnd = scanIdent(text, i, end, fnName);
601	            int k = skipSeparators(text, nameEnd, end);
602	            if (k < 0 || k >= end || text.charAt(k) != '(' || !fnName.toString().equalsIgnoreCase("url")) return false;
603	            int argEnd = matchingParen(text, k + 1, end);
604	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
605	        }
606	        return false;
607	    }
