609	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
610	    boolean isSafeUrlArgument(String value, int from, int end) {
611	        int i = from;
612	        while (i < end && isCssSpace(value.charAt(i))) i++;
613	        int j = end;
614	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
615	        if (i == j) return false; // url() with no reference
616	
617	        char first = value.charAt(i);
618	        String raw;
619	        if (first == '"' || first == '\'') {
620	            int[] quote = scanQuoted(value, i + 1, first);
621	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
622	            raw = value.substring(i + 1, quote[0]);
623	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
624	                char c = raw.charAt(k);
625	                if (c == '\\') { k++; continue; }
626	                if (c == first) return false;
627	            }
628	        } else {
629	            // an unquoted URL token is a single run: a bare quote or whitespace is a syntax error, not part of the
630	            // URL. Whitespace that is the delimiter of a hex escape (or a whitespace character itself escaped) is
631	            // part of the escape and so stays in the run, exactly as a browser reads it.
632	            int k = i;
633	            while (k < j) {
634	                char c = value.charAt(k);
635	                if (c == '\\') {
636	                    int[] escape = consumeEscape(value, k, j);
637	                    if (escape[1] < 0) return false; // a lone trailing backslash is no URL token
638	                    k = escape[0];
639	                    continue;
640	                }
641	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
642	                k++;
643	            }
644	            raw = value.substring(i, j);
645	        }
646	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
647	    }
648	
649	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
650	    int matchingParen(String value, int from, int end) {
651	        int depth = 1;
652	        int i = from;
653	        while (i < end) {
654	            char c = value.charAt(i);
655	            if (c == '\\') { i += 2; continue; }
656	            if (c == '"' || c == '\'') {
657	                int[] quote = scanQuoted(value, i + 1, c);
658	                if (quote[1] != 1) return -1;
659	                i = quote[0] + 1;
660	                continue;
661	            }
662	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
663	                int close = value.indexOf("*/", i + 2);
664	                if (close < 0 || close >= end) return -1; // an unterminated comment leaves the function unclosed
665	                i = close + 2;
666	                continue;
667	            }
668	            if (c == '(') depth++;
669	            else if (c == ')') { depth--; if (depth == 0) return i; }
670	            i++;
671	        }
672	        return -1;
673	    }
674	
675	    /**
676	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
677	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
678	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
679	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
680	     CSS requirement to replace it.
681	     */
682	    static String unescape(String value) {
683	        if (value.indexOf('\\') == -1) return value;
684	        int length = value.length();
685	        StringBuilder sb = null;
686	        int i = 0;
687	        while (i < length) {
688	            char c = value.charAt(i);
689	            if (c == '\\' && i + 1 < length) {
690	                if (sb == null) {
691	                    sb = new StringBuilder(length);
692	                    sb.append(value, 0, i);
693	                }
694	                int h = i + 1;
695	                int hexEnd = h;
696	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
697	                if (hexEnd > h) {
698	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
699	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
700	                    // per the CSS spec, NUL, surrogates, and values above the Unicode range become U+FFFD
701	                    if (code == 0 || code > Character.MAX_CODE_POINT
702	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
703	                        code = 0xFFFD;
704	                    sb.appendCodePoint(code);
705	                    i = hexEnd;
706	                } else {
707	                    sb.append(value.charAt(i + 1));
708	                    i += 2;
709	                }
710	                continue;
711	            }
712	            if (sb != null) sb.append(c);
713	            i++;
714	        }
715	        return sb != null ? sb.toString() : value;
716	    }
717	
718	    static boolean isCssSpace(char c) {
719	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
720	    }
