        "font-family: 'Arial', sans-serif", "--x:2", "@charset \"utf-8\""
    };

    public static void main(String[] args) {
        Random r = new Random(42);
        int iters = 2_000_000;
        int maxLen = 40;
        int crashes = 0, nonIdem = 0, leaks = 0, empties = 0;
        Set<String> crashExamples = new LinkedHashSet<>();
        Set<String> idemExamples = new LinkedHashSet<>();
        Set<String> leakExamples = new LinkedHashSet<>();
        for (int it = 0; it < iters; it++) {
            StringBuilder sb = new StringBuilder();
            int n = 1 + r.nextInt(maxLen);
