            String a = o1 == null ? "" : o1;
            String b = o2 == null ? "" : o2;
            if (!a.equals(b)) {
                nonIdem++;
                if (idemExamples.size() < 10) idemExamples.add("[" + in + "] => [" + a + "] => [" + b + "]");
            }
            if (a.contains("{}")) {
                empties++;
                if (leakExamples.size() < 10) leakExamples.add("EMPTY ["+in+"] => ["+a+"]");
            }
