package org.jsoup.safety;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import java.util.*;

public class FuzzDoc {
    static Safelist sl = Safelist.relaxed().addTags("style").addAttributes(":all", "style")
        .addProtocols(":all", "style", "data");
    static final String[] atoms = {
        "p","div","@media screen","@font-face","@import","{","}",";","(",")","url(","expression(","var(",
        "javascript:1","//cdn/x","data:image/png;base64,iVBOR=","color:red","'x'","\"y\"","/*c*/","/*","*/",
        "\\","\\75 "," ","\n","&amp;","&#106;",",",":","style=\"x:1\"","</style>","<style>","<div style=\"color:red\">",
    };
    public static void main(String[] args) {
        long seed = args.length > 0 ? Long.parseLong(args[0]) : 7L;
        int iters = 1_000_000;
        Random r = new Random(seed);
        int crashes=0, nonIdem=0, mutated=0;
        Set<String> ex = new LinkedHashSet<>();
        for (int it=0; it<iters; it++) {
            StringBuilder sb=new StringBuilder("<style>");
            int n=1+r.nextInt(30);
            for(int k=0;k<n;k++) sb.append(atoms[r.nextInt(atoms.length)]);
            sb.append("</style><style>p{color:red}</style>");
            String html=sb.toString();
            Document d = Jsoup.parseBodyFragment(html, "https://example.com/a/b");
            String before = d.body().html();
            Document o1, o2;
            try { o1 = new Cleaner(sl).clean(d); } catch(Throwable t){ crashes++; if(ex.size()<8) ex.add("CRASH "+t+" :: "+html); continue; }
            try { o2 = new Cleaner(sl).clean(o1); } catch(Throwable t){ crashes++; if(ex.size()<8) ex.add("RECRASH "+t+" :: "+o1.body().html()); continue; }
            if (!before.equals(d.body().html())) { mutated++; if(ex.size()<8) ex.add("MUTATED :: "+html); }
            if (!o1.body().html().equals(o2.body().html())) { nonIdem++; if(ex.size()<8) ex.add("IDEM ["+html+"] => ["+o1.body().html()+"] => ["+o2.body().html()+"]"); }
        }
        System.out.println("seed="+seed+" iters="+iters+" crashes="+crashes+" nonIdem="+nonIdem+" inputMutated="+mutated);
        ex.forEach(s->System.out.println(s));
    }
}
