package org.jsoup.safety;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class Sanity {
    static Safelist sl = Safelist.relaxed().addTags("style").addAttributes(":all", "style");
    static String sheet(String css, String base) {
        Document d = new Cleaner(sl).clean(Jsoup.parseBodyFragment("<style>"+css+"</style>", base));
        var s = d.selectFirst("style"); return s==null?null:s.data();
    }
    public static void main(String[] a) {
        System.out.println(sheet("p{background:image-set(url(x.png) 1x, url(javascript:1) 2x);color:red}", "https://ex.com/a/"));
        System.out.println(sheet("p{background:image(url(https://ex.com/y.png))}", "https://ex.com/a/"));
        System.out.println(sheet("p{background:url(x.png)}", "https://a.example/"));
        System.out.println(sheet("p{background:url(x.png)}", "https://b.example/"));
        // two style elements, order kept
        Document d = new Cleaner(sl).clean(Jsoup.parseBodyFragment(
            "<style>i{color:red;background:url(javascript:1)}</style><style>@media screen}b{color:blue}</style>", "https://ex.com/"));
        d.select("style").forEach(s -> System.out.println("ELEM:["+s.data()+"]"));
    }
}
EOF
